from usg.dsl import *

# Find the signalised crossing at (257, 1718)
crossings = MAP.crossings(control="signals")
crossing_141 = None
for c in crossings:
    if c["id"] == "crossing_141":
        crossing_141 = c
        break

if crossing_141 is None:
    raise ValueError("crossing_141 not found in signalised crossings")

road_id = crossing_141["road"]
road = MAP.road(road_id)
length = road["length"]
s = crossing_141["road_s"]

if length < 30:
    raise ValueError(f"Road {road_id} is too short ({length}m)")

scenario = ScenarioBuilder("cross_with_traffic", MAP, scenario_type="dyn_nav",
                           description="Cross a signalised road while a car approaches; wait for green and avoid the car.")
scenario.user(MAP.crossing_side(crossing_141["id"], "start", inset=2.0))

# Create the signal cycle for crossing_141
signal_name = scenario.signal_cycle(crossing_141["id"], green=15, red=20, initial="red")

# Create a vehicle route that meets the user's crossing path
# Use s as the start point (start of the road segment)
start_place = MAP.lane_center(road_id, s, "forward")
end_place = MAP.lane_center(road_id, min(length, s + 30.0), "forward")

if start_place is None or end_place is None:
    raise ValueError(f"Invalid lane center positions for road {road_id}")

scenario.vehicle("Car1", start_place, [end_place], speed=8.0, model="car_white")

handles = scenario.apply_spec({
    "tasks": [{
        "name": "cross_with_traffic",
        "instruction": "Wait for green, then cross while avoiding the car.",
        "goal": {
            "op": "call",
            "name": "wait_for_green",
            "args": {
                "zone": {"kind": "crossing", "id": "crossing_141"},
                "signal": signal_name
            }
        },
        "safety": [
            {"op": "call", "name": "collision_free", "args": {"entity": "Car1", "r": 0.3}},
            {"op": "call", "name": "obey_signal", "args": {
                "zone": {"kind": "crossing", "id": "crossing_141"},
                "signal": signal_name
            }}
        ],
        "timeout": {"initial": 60, "baseline": 90}
    }]
})
